-- stray – englische Texte (Teil 3), Schlüssel = deutscher Originaltext
local _, ns = ...
local E = ns.LocaleEN

-- bags.lua
E["Beim Zerstören wertvoller Gegenstände steht das Bestätigungswort schon im Feld. Du klickst nur noch auf „Ja“ oder drückst Enter."] = "When destroying valuable items, the confirmation word is already in the box. You just click “Yes” or press Enter."
E["Ohne Nachfrage zerstören"] = "Destroy Without Asking"
E["Zerstört Gegenstände sofort, ohne Ja/Nein-Abfrage – auch epische und legendäre.\n\nZerstörte Gegenstände sind endgültig weg."] = "Destroys items instantly without the yes/no prompt – even epic and legendary ones.\n\nDestroyed items are gone for good."
E["„%s“ vorausfüllen"] = "Prefill “%s”"

-- loot.lua
E["Automatisch plündern"] = "Auto Loot"
E["Ein Klick auf eine Leiche nimmt die ganze Beute. Mit gedrückter Shift-Taste plünderst du wie gewohnt manuell."] = "One click on a corpse takes all the loot. Hold Shift to loot manually as usual."
E["Schnell plündern"] = "Fast Loot"
E["Nimmt die Beute sofort, ohne auf das Beutefenster zu warten. Gegenstände mit Bestätigung fragt WoW weiterhin ab."] = "Takes the loot instantly without waiting for the loot window. WoW still asks about items that need confirmation."
E["Erst „Automatisch plündern“ einschalten (direkt darüber)."] = "Turn on “Auto Loot” first (right above)."

-- freeslots.lua
E["Freie Taschenplätze"] = "Free Bag Slots"
E["Zeigt auf dem Rucksack-Knopf unten an der Leiste, wie viele Plätze in deinen Taschen noch frei sind – rot, wenn alles voll ist. Spezialtaschen wie Köcher zählen nicht mit."] = "Shows on the backpack button at the bottom of the bar how many slots are still free in your bags – red when everything is full. Special bags such as quivers don't count."

-- merchant.lua
E["Automatisch verkaufen"] = "Auto Sell Junk"
E["Verkauft beim Händler alle grauen Gegenstände aus deinen Taschen. Gegenstände, die eine Quest im Questlog noch braucht, verkauft stray dabei nie. Halte Shift gedrückt, um das zu verhindern.\n\nDer Händler kann nur die letzten 12 verkauften Gegenstände zurückkaufen."] = "Sells all gray items from your bags at the vendor. stray never sells items that a quest in your quest log still needs. Hold Shift to prevent this.\n\nThe vendor can only buy back the last 12 items sold."
E["Automatisch reparieren"] = "Auto Repair"
E["Repariert deine Ausrüstung mit deinem Gold, wenn der Händler reparieren kann. Halte Shift gedrückt, um das zu verhindern."] = "Repairs your gear with your gold if the vendor can repair. Hold Shift to prevent this."
E["Nicht genug Gold zum Reparieren."] = "Not enough gold to repair."
E["Ausrüstung für %s repariert."] = "Repaired your gear for %s."
E["1 Gegenstand für %s verkauft."] = "Sold 1 item for %s."
E["%d Gegenstände für %s verkauft."] = "Sold %d items for %s."

-- vendor.lua
E["Verkaufspreis im Tooltip"] = "Sell Price in Tooltip"
E["Zeigt in jedem Gegenstands-Tooltip, was der Händler dafür zahlt. Bei Stapeln steht zusätzlich der Wert des ganzen Stapels dabei (in den Taschen, beim Händler und in der Beute).\n\nZeigt WoW den Preis schon selbst, fügt stray nichts hinzu."] = "Shows in every item tooltip what the vendor pays for it. For stacks, the value of the whole stack is shown as well (in your bags, at the vendor and in the loot window).\n\nIf WoW already shows the price itself, stray adds nothing."
E["Bekanntes grün färben"] = "Color Known Items Green"
E["Verkaufspreis: %s"] = "Sell Price: %s"
E["Stapel (%d): %s"] = "Stack (%d): %s"
E["Rezepte, Begleiter, Reittiere und Bücher, die du schon kennst („%s“), werden beim Händler grün eingefärbt. So kaufst du nichts doppelt."] = "Recipes, pets, mounts and books you already know (“%s”) are colored green at the vendor. That way you never buy anything twice."

-- questitems.lua
E["%s gehört zur Quest „%s“.\nZurückkaufen?"] = "%s belongs to the quest “%s”.\nBuy it back?"
E["Zurückkaufen"] = "Buy Back"
E["Nein"] = "No"
E["Zurückkaufen nicht möglich – ist der Händler noch offen?"] = "Can't buy back – is the vendor still open?"
E["Questgegenstände markieren"] = "Mark Quest Items"
E["Gegenstände, die du für eine Quest in deinem Questlog brauchst, bekommen in den Taschen einen goldenen Rahmen mit „!“. So verkaufst du sie nicht aus Versehen.\n\nErkannt werden Questziele wie „Leinenstoff: 3/10“ – auch schon erfüllte, weil du sie bei der Abgabe noch brauchst."] = "Items you need for a quest in your quest log get a golden border with “!” in your bags. That way you won't sell them by accident.\n\nDetected are quest objectives like “Linen Cloth: 3/10” – including completed ones, because you still need them when turning in."
E["Warnung beim Verkauf"] = "Warn When Selling"
E["Verkaufst du beim Händler einen Gegenstand, den du für eine Quest brauchst, fragt stray sofort nach: „Zurückkaufen?“ – ein Klick holt ihn zum gleichen Preis zurück.\n\nFunktioniert, solange der Händler offen ist."] = "If you sell an item you need for a quest at a vendor, stray asks right away: “Buy back?” – one click gets it back for the same price.\n\nWorks as long as the vendor is open."
E["Rückkauf von %s angefordert."] = "Buyback of %s requested."

-- triage.lua
E["Kein Löschkandidat."] = "No deletion candidate."
E["Auf dem Mauszeiger liegt schon etwas."] = "There is already something on your cursor."
E["stray: billigster Gegenstand – Löschkandidat"] = "stray: cheapest item – deletion candidate"
E["Hilfe bei vollen Taschen"] = "Full Bag Helper"
E["Ist höchstens noch ein Platz frei, markiert stray den billigsten Gegenstand (Verkaufspreis × Anzahl) rot als Löschkandidat – in Blizzards Taschen, im stray-Taschenfenster und im Tooltip. Beute, die mehr wert ist, bekommt beim Plündern eine Goldmünze.\n\nNie vorgeschlagen werden Questgegenstände, angeheftete Gegenstände, Gegenstände ohne Verkaufswert und alles ab „selten“ (blau).\n\nstray löscht nichts selbst. Im stray-Taschenfenster legt „Löschkandidat aufnehmen“ den Gegenstand nur auf den Mauszeiger."] = "When at most one slot is left, stray marks the cheapest item (sell price × count) in red as a deletion candidate – in Blizzard's bags, in the stray bag window and in the tooltip. Loot worth more gets a gold coin while looting.\n\nNever suggested: quest items, pinned items, items without sell value and anything “rare” (blue) or better.\n\nstray never deletes anything itself. In the stray bag window, “Pick Up Deletion Candidate” only puts the item on your cursor."
E["%s liegt auf dem Mauszeiger. Zum Zerstören neben die Fenster klicken – WoW fragt dann nach. Rechtsklick legt ihn zurück."] = "%s is on your cursor. Click outside the windows to destroy it – WoW will ask first. Right-click puts it back."
E["Gegenstand"] = "Item"

