E["Ausrüstung"] = "Gear"
E["Verbrauchbar"] = "Consumables"
E["Handwerk"] = "Trade Goods"
E["Quest"] = "Quest"
E["Neu"] = "New"
E["Angeheftet"] = "Pinned"
E["Taschen"] = "Bags"
E["Suchen …"] = "Search …"
E["Taschen sortieren"] = "Sort Bags"
E["Sortieren geht erst nach dem Kampf."] = "Sorting only works after combat."
E["Sortieren gibt es in diesem Client nicht."] = "This client doesn't support sorting."
E["Sortieren hat nicht geklappt."] = "Sorting didn't work."
E["Keine Gegenstände."] = "No items."
E["Alt+Rechtsklick: anheften"] = "Alt+Right-click: pin"
E["Löschkandidat aufnehmen"] = "Pick Up Deletion Candidate"
E["Legt den rot markierten, billigsten Gegenstand auf den Mauszeiger. stray löscht nichts selbst – das Zerstören bestätigst du bei WoW."] = "Puts the cheapest item, marked in red, on your cursor. stray never deletes anything itself – you confirm destroying it with WoW."
E["Taschenfenster: Blizzards Taschenknopf-Vorlage fehlt – es bleiben Blizzards Taschen."] = "Bag window: Blizzard's bag button template is missing – Blizzard's bags stay in use."
E["Größe ändern geht erst nach dem Kampf."] = "Resizing only works after combat."
E["Ziehen: Größe ändern"] = "Drag: resize"
E["Breite in ganzen Spalten, Höhe frei. Passt nicht alles hinein, blätterst du mit dem Mausrad."] = "Width in whole columns, height is free. If not everything fits, scroll with the mouse wheel."
E["Taschenfenster wird nach dem Kampf aufgebaut – bis dahin Blizzards Taschen."] = "The bag window will be built after combat – until then Blizzard's bags are used."
E["Eigenes Taschenfenster"] = "Custom Bag Window"
E["Zeigt alle Taschen in einem Fenster mit Suche und Kategorien (Ausrüstung, Verbrauchbar, Handwerk, Quest, Neu, Angeheftet). B-Taste, Rucksack-Knopf und Händler öffnen dann dieses Fenster statt Blizzards Taschen.\n\nQuestgegenstände stehen nur unter „Quest“, bis die Quest abgegeben ist.\n\nAlt+Rechtsklick auf einen Gegenstand heftet ihn an oder löst ihn. Kopfzeile ziehen verschiebt das Fenster, der Griff unten rechts ändert die Größe. Passt nicht alles hinein, blätterst du mit dem Mausrad. Der Besen neben der Suche sortiert die Taschen.\n\nAusschalten wirkt sofort; ganz sauber wird es nach Neuladen (/reload)."] = "Shows all bags in one window with search and categories (Gear, Consumables, Trade Goods, Quest, New, Pinned). The B key, the backpack button and vendors then open this window instead of Blizzard's bags.\n\nQuest items are listed only under “Quest” until the quest is turned in.\n\nAlt+right-click an item to pin or unpin it. Drag the header to move the window; the grip at the bottom right resizes it. If not everything fits, scroll with the mouse wheel. The broom next to the search sorts your bags.\n\nTurning it off works immediately; it's fully clean after a reload (/reload)."
E["Spalten im Taschenfenster"] = "Bag Window Columns"
E["Wie viele Plätze nebeneinander im stray-Taschenfenster stehen. Ziehst du das Fenster unten rechts breiter oder schmaler, ändert sich dieser Wert mit."] = "How many slots sit side by side in the stray bag window. If you drag the window wider or narrower at the bottom right, this value changes with it."
E["Erst „Eigenes Taschenfenster“ einschalten (weiter oben)."] = "Turn on “Custom Bag Window” first (further up)."
E["Höhe des Taschenfensters"] = "Bag Window Height"
E["Automatisch"] = "Automatic"
E["Hast du die Höhe unten rechts gezogen, bleibt sie fest. Dieser Knopf stellt wieder auf automatisch: Das Fenster ist dann so hoch wie sein Inhalt (höchstens bildschirmhoch)."] = "If you dragged the height at the bottom right, it stays fixed. This button switches back to automatic: the window is then as tall as its content (at most screen height)."
E["Höhe des Taschenfensters ist wieder automatisch."] = "Bag window height is automatic again."
E["%s gelöst."] = "%s unpinned."
E["%s angeheftet."] = "%s pinned."
E["%d / %d Plätze"] = "%d / %d slots"
